 const stamp=Date.now(); const url=`https://example.com/${stamp}`;
 await page.goto("/"); await expect(page.locator('[data-harness-ready="true"]')).toBeVisible();
 await page.getByLabel("Web address").fill(url); await page.getByLabel("Title").fill("A kept example"); await page.getByLabel(/Short description/).fill("Worth remembering"); await page.getByLabel(/Tags/).fill("reference, calm"); await page.getByRole("button",{name:"Save bookmark"}).click();
 await expect(page.getByRole("link",{name:/A kept example/})).toBeVisible();
 await page.getByLabel("Search bookmarks").fill("remembering"); await expect(page.getByRole("link",{name:/A kept example/})).toBeVisible();
 await page.getByLabel("Search bookmarks").fill(""); await page.getByRole("button",{name:"#reference"}).click(); await expect(page.getByRole("link",{name:/A kept example/})).toBeVisible();
 await page.getByRole("button",{name:"Edit A kept example"}).click(); await page.getByLabel("Title").fill("Edited example"); await page.getByRole("button",{name:"Save changes"}).click(); await expect(page.getByRole("link",{name:/Edited example/})).toBeVisible();
 await page.getByRole("button",{name:"Delete Edited example"}).click(); await page.getByRole("button",{name:"Keep it"}).click(); await expect(page.getByRole("link",{name:/Edited example/})).toBeVisible();
 await page.getByRole("button",{name:"Delete Edited example"}).click(); await page.getByRole("button",{name:"Remove bookmark"}).click(); await expect(page.getByRole("link",{name:/Edited example/})).toHaveCount(0);
});

